import sys; sys.path.insert(0,'/home/claude/pcb/gen')
from schgen import Sheet
S=Sheet('usbblock','OpenCruise USB VBUS-Block adapter',paper='A4')
S.box(10,10,285,150,'USB-A inline adapter: PC (J1 plug) -> DEV (J2 receptacle), VBUS back-feed blocked by D1')
S.part('J1','Connector','USB_A',40,70,{'1':'VBUS_PC','2':'D-','3':'D+','4':'GND','5':'SHIELD'},value='USB-A plug (to PC)',fp='OpenCruise:USB_A_Plug_U-USBAR04P-M',lcsc='C386753',mpn='U-USBAR04P-M001')
S.part('J2','Connector','USB_A',240,70,{'1':'VBUS_DEV','2':'D-','3':'D+','4':'GND','5':'SHIELD'},value='USB-A receptacle (to device)',fp='OpenCruise:USB_A_Receptacle_AF90',lcsc='C456018',mpn='AF 90 WJDG',rot=0)
S.part('D1','Device','D_Schottky',110,45,{'1':'VBUS_DEV','2':'VBUS_PC'},value='B5819W',fp='Diode_SMD:D_SOD-123',lcsc='C8598')
S.part('C1','Device','C',140,50,{'1':'VBUS_DEV','2':'GND'},value='1uF/50V',fp='Capacitor_SMD:C_0603_1608Metric',lcsc='C15849')
S.part('R1','Device','R',110,100,{'1':'SHIELD','2':'GND'},value='1M',fp='Resistor_SMD:R_0603_1608Metric',lcsc='C22935')
S.part('C2','Device','C',125,100,{'1':'SHIELD','2':'GND'},value='4.7nF/50V',fp='Capacitor_SMD:C_0603_1608Metric',lcsc='C53987')
S.part('R2','Device','R',140,100,{'1':'SHIELD','2':'GND'},value='0R',fp='Resistor_SMD:R_0603_1608Metric',lcsc='C21189',dnp=True)
S.part('U1','Power_Protection','USBLC6-2SC6',180,95,{'1':'D+','6':'D+','3':'D-','4':'D-','5':'VBUS_DEV','2':'GND'},value='USBLC6-2SC6',fp='Package_TO_SOT_SMD:SOT-23-6',lcsc='C7519',dnp=True)
S.flag('VBUS_PC',80,120); S.flag('VBUS_DEV',95,120); S.flag('GND',110,128)
S.note('D+/D- pass straight through: 90 ohm differential pair, length matched < 1 mm, no vias.\nD1: PC -> DEV only. Device side (main board 5 V, 4.75-5.1 V) cannot back-feed the PC VBUS.\nU1 (ESD) and R2 (shield-GND 0R) are not fitted by default.',15,135)
S.write('/home/claude/pcb/usbblock/usbblock.kicad_sch')
print(len(S.parts))
